:root {
  color-scheme: light;
  --bg: #f5f6f7;
  --surface: #ffffff;
  --surface-2: #eef1f3;
  --ink: #172026;
  --muted: #66717a;
  --line: #d7dde1;
  --line-strong: #aeb8bf;
  --focus: #111827;
  --shadow: 0 14px 40px rgba(23, 32, 38, 0.14);
  --f1: #bd3150;
  --f2: #13856f;
  --f3: #2d63a7;
  --f4: #c66a12;
  --f5: #7450a8;
  font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-synthesis: none;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--bg);
  color: var(--ink);
}

button,
input,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible {
  outline: 3px solid rgba(45, 99, 167, 0.35);
  outline-offset: 2px;
}

a {
  color: inherit;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: fixed;
  z-index: 1000;
  top: 10px;
  left: 10px;
  padding: 9px 12px;
  background: var(--ink);
  color: white;
  transform: translateY(-150%);
}

.skip-link:focus {
  transform: translateY(0);
}

.app-header {
  display: grid;
  grid-template-columns: minmax(280px, 1.25fr) minmax(360px, 1fr) auto;
  gap: 28px;
  align-items: end;
  padding: 26px clamp(20px, 4vw, 64px) 22px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}

.brand-block h1 {
  margin: 4px 0 5px;
  font-size: clamp(28px, 3vw, 42px);
  line-height: 1.05;
  letter-spacing: 0;
  font-weight: 720;
}

.brand-block p,
.section-note,
.site-footer p {
  margin: 0;
  color: var(--muted);
  line-height: 1.45;
}

.eyebrow,
.section-kicker {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.2;
  font-weight: 750;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.header-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(72px, 1fr));
  gap: 1px;
  overflow: hidden;
  border: 1px solid var(--line);
  background: var(--line);
}

.stat-block {
  min-height: 62px;
  padding: 10px 12px;
  background: var(--surface);
}

.stat-block strong {
  display: block;
  font-size: 23px;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.stat-block span {
  display: block;
  margin-top: 6px;
  color: var(--muted);
  font-size: 11px;
}

.header-actions {
  display: flex;
  gap: 8px;
}

.icon-command {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 7px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  text-decoration: none;
  font-size: 12px;
  font-weight: 700;
}

.icon-command:hover {
  border-color: var(--ink);
}

.icon-command svg,
.view-tab svg,
.search-field svg,
.icon-button svg,
.empty-state svg {
  width: 17px;
  height: 17px;
  stroke-width: 1.8;
}

.view-tabs {
  display: flex;
