  border: 1px solid var(--line-strong);
  border-radius: 4px;
  background: var(--surface);
  color: var(--ink);
}

.search-field input {
  padding: 0 12px 0 39px;
}

.select-field {
  display: grid;
  gap: 3px;
}

#!/usr/bin/env python3
"""Build the static input-representation taxonomy atlas and its evidence data."""

from __future__ import annotations

