.table-shell {
  overflow-x: auto;
  border: 1px solid var(--line);
  background: var(--surface);
}

.evidence-table {
  width: 100%;
  min-width: 980px;
  border-collapse: collapse;
  table-layout: fixed;
}

.evidence-table th,
.evidence-table td {
  padding: 11px 12px;
  border-bottom: 1px solid var(--line);
  text-align: left;
  vertical-align: top;
}

.evidence-table th {
  position: sticky;
  z-index: 1;
  top: 0;
  background: #edf0f2;
  color: #4e5961;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.evidence-table th:nth-child(1) { width: 17%; }
.evidence-table th:nth-child(2) { width: 29%; }
.evidence-table th:nth-child(3) { width: 20%; }
.evidence-table th:nth-child(4) { width: 34%; }

.evidence-table td {
  font-size: 11px;
  line-height: 1.42;
}

.evidence-table tr:last-child td {
  border-bottom: 0;
}

.model-link {
  display: block;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--ink);
  text-align: left;
  cursor: pointer;
  font-weight: 800;
}

.model-link:hover {
  text-decoration: underline;
}

.cell-muted {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 9px;
}

.route-chain {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  align-items: center;
}

.chain-node {
  padding: 3px 5px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: #f8f9fa;
}

.chain-arrow {
  color: var(--muted);
}

.evidence-quote {
  margin: 0;
  padding-left: 9px;
  border-left: 3px solid var(--family-color);
  color: #354048;
}

.pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 12px;
}

.page-button {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  gap: 6px;
  padding: 7px 10px;
  border: 1px solid var(--line-strong);
  border-radius: 4px;
  background: var(--surface);
  cursor: pointer;
  font-size: 11px;
  font-weight: 750;
}

.page-button:disabled {
  opacity: 0.45;
  cursor: default;
}

.page-status {
  color: var(--muted);
  font-size: 11px;
}

.architecture-dialog {
  width: min(1240px, calc(100vw - 36px));
  max-height: calc(100vh - 36px);
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: 6px;
  background: var(--surface);
  color: var(--ink);
  box-shadow: var(--shadow);
}

.architecture-dialog::backdrop {
  background: rgba(13, 19, 23, 0.64);
}

.dialog-header {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 20px;
  padding: 19px 22px 16px;
  border-bottom: 1px solid var(--line);
}

.dialog-header h2 {
  margin: 4px 0 0;
  font-size: 28px;
  line-height: 1.1;
}

.dialog-body {
  max-height: calc(100vh - 130px);
  overflow-y: auto;
  overscroll-behavior: contain;
}

.dialog-overview {
  display: grid;
  grid-template-columns: minmax(360px, 0.9fr) minmax(420px, 1.1fr);
  border-bottom: 1px solid var(--line-strong);
}

.source-figure {
  margin: 0;
  padding: 20px;
  border-right: 1px solid var(--line);
  background: #edf0f2;
}

.source-figure a {
  display: block;
  overflow: hidden;
  border: 1px solid var(--line-strong);
  background: white;
}

.source-figure img {
  display: block;
  width: 100%;
  max-height: 480px;
  object-fit: contain;
}

.source-figure figcaption {
  margin-top: 10px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.45;
}

.figure-provenance {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 8px;
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 9px;
}

.architecture-summary {
  padding: 22px;
}

.architecture-summary h3,
.routes-section h3 {
  margin: 0 0 8px;
  font-size: 15px;
}

.architecture-summary .paper-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;

.example-row {
  display: grid;
  grid-template-columns: 220px minmax(180px, 1fr) 32px minmax(220px, 1fr) 32px minmax(180px, 0.8fr);
  gap: 12px;
  align-items: center;
  padding: 16px 12px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.example-row:hover {
  background: #fafbfb;
}

.example-name {
  border-left: 4px solid var(--family-color);
  padding-left: 10px;
}

.example-name strong,
.example-name span {
  display: block;
}

.example-name strong {
  font-size: 13px;
}

.example-name span {
  margin-top: 4px;
  color: var(--muted);
  font-size: 10px;
}

.example-stage {
  min-width: 0;
}

.example-stage label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.example-stage code {
  display: block;
  overflow-wrap: anywhere;
  color: var(--ink);
  font-family: "SFMono-Regular", Consolas, monospace;
  font-size: 11px;
  line-height: 1.45;
}

.example-arrow {
  color: var(--family-color);
  text-align: center;
  font-size: 20px;
}

.result-count {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}

.architecture-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.architecture-card {
  display: grid;
  grid-template-rows: 172px auto;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--surface);
}

.architecture-card:hover {
  border-color: var(--line-strong);
  box-shadow: 0 8px 22px rgba(23, 32, 38, 0.09);
}

.card-figure {
  position: relative;
  display: block;
  width: 100%;
  height: 172px;
  overflow: hidden;
  border: 0;
  border-bottom: 1px solid var(--line);
  background: #e6eaed;
  cursor: pointer;
}

.card-figure img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top center;
  transition: transform 180ms ease;
}

.architecture-card:hover .card-figure img {
  transform: scale(1.025);
}

.figure-index {
  position: absolute;
  right: 8px;
  bottom: 8px;
  padding: 4px 6px;
  background: rgba(23, 32, 38, 0.9);
  color: white;
  font-size: 9px;
  font-weight: 800;
}

.card-content {
  display: grid;
  align-content: start;
  min-height: 226px;
  padding: 14px;
}

.card-content h3 {
  margin: 0;
  overflow-wrap: anywhere;
  font-size: 17px;
  line-height: 1.2;
}

.paper-title {
  display: -webkit-box;
  min-height: 34px;
  margin: 6px 0 10px;
  overflow: hidden;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.45;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.tag-row {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-bottom: 12px;
}

.family-tag,
.meta-tag {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 3px 6px;
  border-radius: 3px;
  font-size: 9px;
  font-weight: 800;
}

.family-tag {
  background: color-mix(in srgb, var(--family-color) 11%, white);
  color: var(--family-color);
  border: 1px solid color-mix(in srgb, var(--family-color) 30%, white);
}

.meta-tag {
  background: var(--surface-2);
  color: var(--muted);
}

.card-route-preview {
  display: grid;
  gap: 5px;
  margin: 0 0 12px;
  padding: 0;
  list-style: none;
}

.card-route-preview li {
  display: grid;
  grid-template-columns: 7px 1fr;
  gap: 6px;
  min-width: 0;
  color: #364149;
  font-size: 10px;
  line-height: 1.3;
}

.route-dot {
  width: 7px;
  height: 7px;
  margin-top: 3px;
  border-radius: 50%;
  background: var(--family-color);
}

.inspect-button {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin-top: auto;
  padding: 9px 0 0;
  border: 0;
  border-top: 1px solid var(--line);
  background: transparent;
  color: var(--ink);
  cursor: pointer;
  font-size: 11px;
  font-weight: 800;
}

.inspect-button:hover {
  color: var(--primary-family, var(--ink));
}

.inspect-button svg {
  width: 15px;
}

.empty-state {
  padding: 80px 20px;
  color: var(--muted);
  text-align: center;
}

.empty-state svg {
  width: 30px;
  height: 30px;
}

  gap: 5px;
  color: #245c91;
  font-size: 12px;
  font-weight: 700;
}

.architecture-summary .paper-link svg {
  width: 14px;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 20px;
  border-top: 1px solid var(--line);
  border-left: 1px solid var(--line);
}

.summary-item {
  min-width: 0;
  padding: 11px;
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.summary-item label {
  display: block;
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.summary-item div {
  overflow-wrap: anywhere;
  font-size: 11px;
  line-height: 1.4;
}

.routes-section {
  padding: 22px;
}

.routes-toolbar {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 13px;
}

.route-detail-list {
  display: grid;
  gap: 12px;
}

.route-detail {
  overflow: hidden;
  border: 1px solid var(--line);
  border-left: 5px solid var(--family-color);
  border-radius: 4px;
}

.route-detail summary {
  display: grid;
  grid-template-columns: minmax(180px, 1fr) auto;
  gap: 16px;
  align-items: center;
  min-height: 54px;
  padding: 11px 13px;
  background: #fafbfb;
  cursor: pointer;
  list-style: none;
}

.route-detail summary::-webkit-details-marker {
  display: none;
}

.route-detail summary strong {
  display: block;
  font-size: 12px;
}

.route-detail summary span {
  color: var(--muted);
  font-size: 9px;
}

.route-detail-content {
  padding: 14px;
  border-top: 1px solid var(--line);
}

.route-pipeline {
  display: grid;
  grid-template-columns: minmax(150px, 0.8fr) 28px minmax(200px, 1.2fr) 28px minmax(160px, 0.9fr);
  gap: 8px;
  align-items: stretch;
}

.pipeline-stage {
  padding: 10px;
  border: 1px solid var(--line);
  background: #f8f9fa;
}

.pipeline-stage label {
  display: block;
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.pipeline-stage p,
.pipeline-stage ol {
  margin: 0;
  padding-left: 16px;
  font-size: 10px;
  line-height: 1.45;
}

.pipeline-stage p {
  padding-left: 0;
}

.pipeline-arrow {
  display: grid;
  place-items: center;
  color: var(--family-color);
  font-size: 20px;
}

.grounding-block {
  display: grid;
  grid-template-columns: 1fr minmax(190px, 0.45fr);
  gap: 16px;
  margin-top: 13px;
  padding-top: 13px;
  border-top: 1px solid var(--line);
}

.grounding-block blockquote {
  margin: 0;
  padding-left: 12px;
  border-left: 3px solid var(--family-color);
  font-family: Georgia, serif;
  font-size: 12px;
  line-height: 1.5;
}

.grounding-meta {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.site-footer {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  padding: 20px clamp(20px, 4vw, 64px) 30px;
  border-top: 1px solid var(--line);
  background: var(--surface);
  font-size: 10px;
}

.loading-screen {
  position: fixed;
  z-index: 100;
  inset: 0;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 12px;
  background: var(--bg);
  color: var(--muted);
  transition: opacity 180ms ease, visibility 180ms ease;
}

.loading-screen.is-hidden {
  opacity: 0;
  visibility: hidden;
}

.loading-mark {
  width: 34px;
  height: 34px;
  border: 3px solid var(--line);
  border-top-color: var(--f3);
  border-radius: 50%;
  animation: spin 700ms linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

@media (max-width: 1180px) {
  .app-header {
    grid-template-columns: 1fr auto;
  }

  .header-stats {
    grid-column: 1 / -1;
    grid-row: 2;
  }

  .header-actions {
    grid-column: 2;
    grid-row: 1;
  }

  .filter-bar {
    grid-template-columns: minmax(260px, 1fr) minmax(300px, auto) repeat(3, minmax(140px, 0.6fr)) 38px;
  }

  .architecture-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .family-definition {
    min-height: 126px;
  }
}

@media (max-width: 940px) {
  .filter-bar {
    position: static;
    grid-template-columns: 1fr 1fr 1fr 38px;
  }

  .search-field,
  .family-filter {
    grid-column: span 2;
  }

  .modality-field {
    grid-column: span 2;
  }

  .family-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .family-column:nth-child(odd) {
    border-left: 0;
  }

  .family-definition {
    min-height: 0;
  }

  .architecture-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .example-row {
    grid-template-columns: 190px 1fr 24px 1fr;
  }

  .example-row .example-stage:last-child {
    grid-column: 2 / -1;
  }

  .example-row .example-arrow:nth-last-child(2) {
    display: none;
  }

  .dialog-overview {
    grid-template-columns: 1fr;
  }

  .source-figure {
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }
}

}

@media (max-width: 680px) {
  .app-header {
    grid-template-columns: 1fr;
    gap: 16px;
    padding: 20px 16px 17px;
  }

  .header-actions {
    grid-column: 1;
    grid-row: 2;
  }

  .header-stats {
    grid-column: 1;
    grid-row: 3;
    grid-template-columns: repeat(2, 1fr);
  }

  .view-tabs {
    padding: 8px 8px 0;
    overflow-x: auto;
  }

  .view-tab {
    flex: 0 0 auto;
    padding-inline: 11px;
  }

  .filter-bar {
    grid-template-columns: 1fr 38px;
    padding: 10px 12px;
  }

  .search-field,
  .family-filter,
  .select-field,
  .modality-field {
    grid-column: 1 / -1;
  }

  .filter-bar .icon-button {
    grid-column: 2;
  }

  .view-panel {
    padding: 22px 12px 46px;
  }

  .section-heading {
    display: block;
  }

  .section-heading .section-note,
  .result-count {
    margin-top: 10px;
  }

  .family-grid {
    grid-template-columns: 1fr;
  }

  .family-column,
  .family-column:nth-child(odd) {
    border-left: 0;
    border-top: 1px solid var(--line);
  }

  .family-column:first-child {
    border-top: 0;
  }

  .map-lane {
    grid-template-columns: 1fr;
  }

  .lane-label {
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .architecture-grid {
    grid-template-columns: 1fr;
  }

  .architecture-card {
    grid-template-columns: 128px 1fr;
    grid-template-rows: auto;
  }

  .card-figure {
    height: 100%;
    min-height: 240px;
    border-right: 1px solid var(--line);
    border-bottom: 0;
  }

  .card-content {
    min-height: 240px;
    padding: 12px;
  }

  .example-row {
    grid-template-columns: 1fr;
    gap: 9px;
  }

  .example-arrow {
    transform: rotate(90deg);
  }

  .example-row .example-stage:last-child {
    grid-column: auto;
  }

  .example-row .example-arrow:nth-last-child(2) {
    display: block;
  }

  .site-footer {
    display: grid;
  }

  .architecture-dialog {
    width: 100vw;
    max-width: 100vw;
    max-height: 100vh;
    height: 100vh;
    margin: 0;
    border: 0;
    border-radius: 0;
  }

  .dialog-header {
    padding: 15px 14px;
  }

  .dialog-header h2 {
    font-size: 22px;
  }

  .dialog-body {
    max-height: calc(100vh - 74px);
  }

  .source-figure,
  .architecture-summary,
  .routes-section {
    padding: 14px;
  }

  .summary-grid {
    grid-template-columns: 1fr;
  }

  .route-pipeline {
    grid-template-columns: 1fr;
  }

  .pipeline-arrow {
    transform: rotate(90deg);
  }

  .grounding-block {
    grid-template-columns: 1fr;
  }
}

