268	function routeChain(route) {
269	  const transforms = (route.transformation_chain_verbatim || []).slice(0, 3);
270	  const nodes = [
271	    `<span class="chain-node">${escapeHtml(route.source_object_verbatim)}</span>`,
272	    ...transforms.flatMap((item) => [
273	      `<span class="chain-arrow">→</span>`,
274	      `<span class="chain-node">${escapeHtml(item)}</span>`,
275	    ]),
276	    `<span class="chain-arrow">→</span>`,
277	    `<span class="chain-node">${escapeHtml(route.model_visible_form_verbatim)}</span>`,
278	  ];
279	  return nodes.join("");
280	}
