 91	function architectureMatches(architecture, forcedFamily = "") {
 92	  const family = forcedFamily || state.family;
 93	  if (family && !architecture.families.includes(family)) return false;
 94	  if (state.subtype && !architecture.subtypes.includes(state.subtype)) return false;
 95	  if (state.lifecycle && !architecture.lifecycle_phases.includes(state.lifecycle)) return false;
 96	  if (state.modality && !architecture.modalities.includes(state.modality)) return false;
 97	  if (!state.query) return true;
 98	  const query = state.query.toLocaleLowerCase();
 99	  const haystack = [
100	    architecture.model_name,
101	    architecture.paper_title,
102	    architecture.doi,
103	    ...architecture.modalities,
104	    ...architecture.lifecycle_phases,
105	    ...architecture.fusion_topologies,
106	    ...architecture.routes.flatMap((route) => [
107	      route.route_label,
108	      route.source_object_verbatim,
109	      route.model_visible_form_verbatim,
110	      route.evidence_quote,
111	      route.section_heading,
112	    ]),
113	  ]
114	    .join(" ")
115	    .toLocaleLowerCase();
116	  return haystack.includes(query);
117	}
